-- Order alerts for the owner dashboard (/admin): Web Push subscriptions of
-- the owner's devices, and the store's VAPID key pair (generated by the
-- Worker on first use). Service role only: browser roles get nothing.
create table if not exists public.admin_push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  created_at timestamptz not null default now(),
  endpoint text not null unique check (endpoint ~ '^https://'),
  p256dh text not null,
  auth text not null,
  label text check (label is null or char_length(label) <= 80),
  last_sent_at timestamptz,
  failures integer not null default 0
);
alter table public.admin_push_subscriptions enable row level security;
revoke all on public.admin_push_subscriptions from anon, authenticated;

create table if not exists public.admin_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);
alter table public.admin_settings enable row level security;
revoke all on public.admin_settings from anon, authenticated;
